import json,numpy as np
from rcb_client import Robot
r=Robot();o=r.get_obs(cameras=('right_camera',),include_depth=True,video='none');n=np.asarray(o.meta['proprio']['now'],float);D=np.asarray(o.depth['right_camera']).squeeze()
m=json.load(open('/app/output/attempt_01_pregrasp/meta.json'));C0=np.array(m['cameras']['right_camera']['cam2world_gl'],float)
def qR(q):
 w,x,y,z=np.array(q)/np.linalg.norm(q);return np.array([[1-2*(y*y+z*z),2*(x*y-z*w),2*(x*z+y*w)],[2*(x*y+z*w),1-2*(x*x+z*z),2*(y*z-x*w)],[2*(x*z-y*w),2*(y*z+x*w),1-2*(x*x+y*y)]])
def T(p,q):
 t=np.eye(4);t[:3,:3]=qR(q);t[:3,3]=p;return t
E0=T([.306433141,-.31279975,.9409984],[.70356256,0,0,.71063328]);E=T(n[21:24],n[24:28]);C=E@np.linalg.inv(E0)@C0@np.diag([1,-1,-1,1]);
print('time',o.meta['time_left_s'],'ee',n[21:28]); print('cam',C[:3,3], 'fwd',C[:3,2])
for v in [110,130,150,170,190,210]:
 row=[]
 for u in [265,275,285,295,305]: row.append(float(D[v,u]))
 print(v,row)
for u,v in [(282,120),(282,150),(282,180),(282,205),(286,170),(276,170),(292,170)]:
 d=float(D[v,u])/1000; pc=np.array([(u-160)/358.642*d,(v-120)/358.642*d,d,1]); pw=C@pc;print((u,v),d,np.round(pw[:3],3))
